    fn failures(&self) -> impl Iterator<Item = &GLLFailure> {
        self.failures.iter()
    }
    #[inline(never)]
    fn add_failure(
        &mut self,
        input_index: u32,
        slot_id: SlotId,
        gss_node_id: Option<GssNodeId>,
        kind: GLLFailureKind,
    ) {
        if self.suppress_failures {
            return;
        }
        let level = self.failures.first().map_or(0, |e| e.input_index);
        record!(self, GLLFailure, input_index, slot_id, gss_node_id, kind);
        if input_index < level {
            return;
        }
        if input_index > level {
            self.failures.clear();
        }
        if self.failures.last().is_some_and(|last| last.kind == kind) {
            return;
        }
        self.failures.push(
            GLLFailure {
                input_index,
                slot_id,
                gss_node_id,
                kind,
            },
            self.vec_arena,
        );
    }
    fn match_token(&mut self, terminal_id: TerminalId, input_index: u32) -> Option<u32> {
        self.scanner.match_token(terminal_id, input_index)
    }
    fn match_any(&mut self, set: &'static TerminalSet, input_index: u32) -> bool {
        self.scanner.match_any(set, input_index)
    }
    fn predict(&mut self, prediction: &'static Prediction, input_index: u32) -> Self::Alternatives {
        self.scanner.predict(prediction, input_index)
    }
    fn vec_arena(&self) -> &'arena Arena {
        self.vec_arena
    }
