    fn parse_requires_modifier_ll1(
        &mut self,
        i: u32,
        failure_context: Option<(SlotId, Option<GssNodeId>)>,
    ) -> Option<SPPFNodeId> {
        #[cfg(feature = "instrument")]
        self.ll1_call_log.push((NonterminalId(5), i));
        let result = (|| -> Option<SPPFNodeId> {
            let matched = self
                .scanner
                .longest_match(&FIRST_SET_REQUIRES_MODIFIER, i)?;
            match matched {
                TerminalId(68) => {
                    let mut j = i;
                    if !(j == 0 || self.scanner.match_token(TerminalId(156), j - 1).is_none()) {
                        return None;
                    }
                    let right_child = {
                        let start = j;
                        let (end, node) =
                            self.match_terminal(TerminalId(68), start, SlotId(69), None)?;
                        if let Some(failure) = self.post_conditions(SlotId(69), start, end) {
                            self.add_failure(end, SlotId(69), None, failure);
                            return None;
                        }
                        j = end;
                        node
                    };
                    let left_extent = self.sppf_node(right_child).left_extent();
                    let current = right_child;
                    Some(self.add_nonterminal_node(NonterminalNode {
                        nonterminal_id: NonterminalId(5),
                        return_slot: SlotId(69),
                        span: Span {
                            left_extent,
                            right_extent: j,
                        },
                        child: current,
                        ambiguous: false,
                    }))
                }
                TerminalId(69) => {
                    let mut j = i;
                    if !(j == 0 || self.scanner.match_token(TerminalId(156), j - 1).is_none()) {
                        return None;
                    }
                    let right_child = {
                        let start = j;
                        let (end, node) =
                            self.match_terminal(TerminalId(69), start, SlotId(71), None)?;
                        if let Some(failure) = self.post_conditions(SlotId(71), start, end) {
                            self.add_failure(end, SlotId(71), None, failure);
                            return None;
                        }
                        j = end;
                        node
                    };
                    let left_extent = self.sppf_node(right_child).left_extent();
                    let current = right_child;
                    Some(self.add_nonterminal_node(NonterminalNode {
                        nonterminal_id: NonterminalId(5),
                        return_slot: SlotId(71),
                        span: Span {
                            left_extent,
                            right_extent: j,
                        },
                        child: current,
                        ambiguous: false,
                    }))
                }
                _ => unreachable!("LL(1) dispatch covers every terminal in FIRST_SET"),
            }
        })();
        if result.is_none() {
            if let Some((slot_id, gss_node_id)) = failure_context {
                self.add_failure(
                    i,
                    slot_id,
                    gss_node_id,
                    GLLFailureKind::UnexpectedToken(&FIRST_SET_REQUIRES_MODIFIER),
                );
            }
        }
        result
    }
