    fn parse_plus_49_ll1(
        &mut self,
        i: u32,
        failure_context: Option<(SlotId, Option<GssNodeId>)>,
    ) -> Option<SPPFNodeId> {
        #[cfg(feature = "instrument")]
        self.ll1_call_log.push((NonterminalId(320), i));
        let result = (|| -> Option<SPPFNodeId> {
            let mut j = i;
            let (body_node, body_end) = (self
                .match_terminal(TerminalId(36), j, SlotId(2058), None)
                .map(|(end, node)| (node, end)))?;
            j = body_end;
            let left_extent = i;
            let mut current = self.add_nonterminal_node(NonterminalNode {
                nonterminal_id: NonterminalId(320),
                return_slot: SlotId(2059),
                span: Span {
                    left_extent,
                    right_extent: j,
                },
                child: body_node,
                ambiguous: false,
            });
            #[allow(clippy::while_let_loop)]
            loop {
                let Some((node_0, pos_0)) = self.parse_layout_ll1(j, None).map(|node| {
                    let end = self.sppf_node(node).right_extent();
                    (node, end)
                }) else {
                    break;
                };
                let Some((node_1, pos_1)) = self
                    .match_terminal(TerminalId(63), pos_0, SlotId(2054), None)
                    .map(|(end, node)| (node, end))
                else {
                    break;
                };
                let Some((node_2, pos_2)) = self.parse_layout_ll1(pos_1, None).map(|node| {
                    let end = self.sppf_node(node).right_extent();
                    (node, end)
                }) else {
                    break;
                };
                let Some((node_3, pos_3)) = self
                    .match_terminal(TerminalId(36), pos_2, SlotId(2056), None)
                    .map(|(end, node)| (node, end))
                else {
                    break;
                };
                j = pos_3;
                current = self.create_intermediate_node_ll1(
                    SlotId(2054),
                    left_extent,
                    pos_0,
                    current,
                    node_0,
                );
                current = self.create_intermediate_node_ll1(
                    SlotId(2055),
                    left_extent,
                    pos_1,
                    current,
                    node_1,
                );
                current = self.create_intermediate_node_ll1(
                    SlotId(2056),
                    left_extent,
                    pos_2,
                    current,
                    node_2,
                );
                current = self.create_intermediate_node_ll1(
                    SlotId(2057),
                    left_extent,
                    pos_3,
                    current,
                    node_3,
                );
                current = self.add_nonterminal_node(NonterminalNode {
                    nonterminal_id: NonterminalId(320),
                    return_slot: SlotId(2057),
                    span: Span {
                        left_extent,
                        right_extent: j,
                    },
                    child: current,
                    ambiguous: false,
                });
            }
            Some(current)
        })();
        if result.is_none() {
            if let Some((slot_id, gss_node_id)) = failure_context {
                self.add_failure(
                    i,
                    slot_id,
                    gss_node_id,
                    GLLFailureKind::UnexpectedToken(&FIRST_SET_PLUS_49),
                );
            }
        }
        result
    }
