    fn parse_opt_72_ll1(
        &mut self,
        i: u32,
        _failure_context: Option<(SlotId, Option<GssNodeId>)>,
    ) -> Option<SPPFNodeId> {
        #[cfg(feature = "instrument")]
        self.ll1_call_log.push((NonterminalId(323), i));
        let Some(matched) = self.scanner.longest_match(&FIRST_SET_OPT_72, i) else {
            return {
                let epsilon_node_id = self.get_or_create_epsilon_node(i);
                Some(self.add_nonterminal_node(NonterminalNode {
                    nonterminal_id: NonterminalId(323),
                    return_slot: SlotId(2071),
                    span: Span {
                        left_extent: i,
                        right_extent: i,
                    },
                    child: epsilon_node_id,
                    ambiguous: false,
                }))
            };
        };
        match matched {
            TerminalId(51) | TerminalId(50) => {
                let mut j = i;
                let right_child = {
                    let start = j;
                    let node = self.parse_plus_50_ll1(start, Some((SlotId(2070), None)))?;
                    let end = self.sppf_node(node).right_extent();
                    j = end;
                    node
                };
                let left_extent = self.sppf_node(right_child).left_extent();
                let current = right_child;
                Some(self.add_nonterminal_node(NonterminalNode {
                    nonterminal_id: NonterminalId(323),
                    return_slot: SlotId(2070),
                    span: Span {
                        left_extent,
                        right_extent: j,
                    },
                    child: current,
                    ambiguous: false,
                }))
            }
            _ => unreachable!("LL(1) dispatch covers every terminal in FIRST_SET"),
        }
    }
